import{_ as a,o,c as s,a3 as r}from"./chunks/framework.BFeCKmyl.js";const p=JSON.parse('{"title":"Alertas menos intrusivos","description":"","frontmatter":{"title":"Alertas menos intrusivos","id":"eproc-alertas-inline","plataforma":"eproc","grupo":"Geral do eproc","plano":"free","desde":"1.2.0","padrao":"desligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-alertas-inline"}]]},"headers":[],"relativePath":"funcionalidades/eproc-alertas-inline.md","filePath":"funcionalidades/eproc-alertas-inline.md"}'),t={name:"funcionalidades/eproc-alertas-inline.md"};function i(n,e,c,l,d,u){return o(),s("div",null,e[0]||(e[0]=[r('<h1 id="alertas-menos-intrusivos" tabindex="-1">Alertas menos intrusivos <a class="header-anchor" href="#alertas-menos-intrusivos" aria-label="Permalink to &quot;Alertas menos intrusivos&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Substitui as caixas de mensagem do eproc (como &quot;Utilize o botão &#39;Sair do Sistema&#39; caso queira efetuar um novo login&quot;), que travam a navegação até você clicar em OK, por um aviso discreto no topo da janela. O aviso fecha sozinho, e os alertas ficam num histórico para consulta.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, em todas as telas: aviso centralizado no topo da janela e, quando há alertas fechados sem confirmação, um ícone com contador no menu superior.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Ligue o recurso nas configurações do eploc (ele vem desligado).</li><li>Quando o eproc emitir um alerta, ele aparece como aviso no topo. Clique em <strong>OK</strong> para fechá-lo, ou aguarde: uma barra mostra o tempo restante, que pausa enquanto o mouse está sobre o aviso ou a aba está em segundo plano.</li><li>Se algum alerta fechar sozinho, aparece no menu superior um ícone com contador. Clique nele (ou clique com o botão direito em qualquer aviso) para abrir o histórico dos últimos 7 dias. Ali você pode copiar o texto de cada alerta e abrir a página de origem.</li><li>Para que um tipo de aviso pare de ir para o histórico, use <strong>Rotineiro...</strong> no histórico e escolha o trecho que identifica aquele aviso (use <code>*</code> nas partes que mudam). O aviso continua aparecendo, mas não é mais registrado.</li><li>Para não ver mais um tipo de aviso, clique no botão ▾ ao lado do OK (&quot;Mais opções&quot;) e escolha o trecho que o identifica. Avisos com esse trecho deixam de aparecer.</li></ol><p>Os avisos rotineiros e ocultos podem ser revistos e desfeitos nas configurações do eploc, no card do recurso, em <strong>Gerenciar avisos rotineiros e ocultos</strong>.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Fechar automaticamente o banner após</td><td>15 segundos</td><td>De 5 a 60 segundos.</td></tr><tr><td>Manter histórico dos últimos alertas (avisa sobre os fechados sem clicar em OK)</td><td>ligada</td><td>Desligada, não há histórico nem ícone no menu.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li><strong>Atenção:</strong> com o alerta nativo, o eproc espera o clique em OK antes de continuar a tarefa. Com este recurso, o eproc segue imediatamente, sem esperar. Por isso o recurso vem desligado.</li><li>Um aviso oculto some sem deixar rastro. O gerenciador mostra quantas vezes cada trecho ocultou avisos, para você conferir se ele não está pegando mais do que devia.</li><li>Avisos que o eproc manda com o texto repetido aparecem uma vez só.</li></ul>',12)]))}const h=a(t,[["render",i]]);export{p as __pageData,h as default};
